def is_small_prime(
    number: int
) -> bool:
    """Check whether :paramref:`number` is a prime smaller than 10."""
    for prime in [2, 3, 5, 7]:
        if prime == number:
            return True
    return False


def count_and_lengths_of(
    texts: Sequence[str]
) -> List[int]:
    """Give the number of :paramref:`texts` followed by their lengths."""
    result = [len(texts)]
    for text in texts:
        result.append(len(text))
    return result


def positives_of(
    numbers: Sequence[int]
) -> List[int]:
    """Give the positive :paramref:`numbers` in the same order."""
    result: List[int] = []
    for number in numbers:
        if number > 0:
            result.append(number)
    return result


def ints_are_unique(
    numbers: Sequence[int]
) -> bool:
    """
    Check that :paramref:`numbers` are unique with a local list of the seen.
    """
    seen: List[int] = []
    for number in numbers:
        if number in seen:
            return False
        seen.append(number)
    return True


def contains_by_loop(
    number: int,
    numbers: Sequence[int]
) -> bool:
    """
    Check whether :paramref:`number` is in :paramref:`numbers`, item by item.

    Java boxes both :paramref:`number` and the items as ``Long``'s, so that ``==``
    would compare their references. The test data looks up the numbers beyond -128
    and 127 on purpose, as Java caches the boxed values in that range, and
    the references would be equal by chance.
    """
    for other in numbers:
        if other == number:
            return True
    return False


def floats_are_unique(
    numbers: Sequence[float]
) -> bool:
    """
    Check that :paramref:`numbers` are unique by comparing them pair-wise.

    Java boxes the items as ``Double``'s, so that ``==`` would compare their
    references.
    """
    for i in range(0, len(numbers)):
        for j in range(i + 1, len(numbers)):
            if numbers[i] == numbers[j]:
                return False
    return True


def is_separator(
    text: str
) -> bool:
    """Check whether :paramref:`text` is one of the separators."""
    return text in ['.', ',', ';']


def is_in_ints(
    number: int,
    numbers: Sequence[int]
) -> bool:
    """Check whether :paramref:`number` is in :paramref:`numbers`."""
    return number in numbers


def is_in_optional_strings(
    text: str,
    texts: Optional[Sequence[str]]
) -> bool:
    """
    Check whether :paramref:`text` is in :paramref:`texts`, if specified.
    """
    if texts is None:
        return False
    return text in texts


def contains_dot(
    text: str
) -> bool:
    """Check whether :paramref:`text` contains a dot."""
    return '.' in text


class _Transformer(
        our_types.AbstractTransformer[
            Iterator[Error]
        ]
):
    # noinspection PyMethodMayBeStatic
    def transform_something(
            self,
            that: our_types.Something
    ) -> Iterator[Error]:
        if not (
            all(
                not is_small_prime(number)
                for number in that.some_ints
            )
        ):
            yield Error(
                'Some ints must not contain small primes.'
            )

        if not (
            all(
                number <= 10
                for number in count_and_lengths_of(that.some_strings)
            )
        ):
            yield Error(
                'There must be at most 10 strings of at most 10 characters ' +
                'each.'
            )

        if not (len(positives_of(that.some_ints)) <= 1):
            yield Error(
                'At most one of some ints must be positive.'
            )

        if not (not (0 in that.some_ints)):
            yield Error(
                'Ints must not contain zero.'
            )

        if not (
            not is_in_ints(len(that.some_strings), that.some_ints)
        ):
            yield Error(
                'Ints must not contain the number of strings.'
            )

        if not (not (-1.0 in that.some_floats)):
            yield Error(
                'Floats must not contain minus one.'
            )

        if not (not is_in_optional_strings('', that.some_strings)):
            yield Error(
                'Strings must not contain an empty string.'
            )

        if not (
            all(
                not contains_dot(text)
                for text in that.some_strings
            )
        ):
            yield Error(
                'Strings must not contain dots.'
            )

        if not ints_are_unique(that.some_ints):
            yield Error(
                'Some ints must be unique.'
            )

        if not (
            all(
                not is_separator(text)
                for text in that.some_strings
            )
        ):
            yield Error(
                'Some strings must not be separators.'
            )

        if not (not contains_by_loop(-500, that.some_ints)):
            yield Error(
                'Some ints must not contain -500.'
            )

        if not floats_are_unique(that.some_floats):
            yield Error(
                'Some floats must be unique.'
            )


_TRANSFORMER = _Transformer()


def verify(
        that: our_types.Class
) -> Iterator[Error]:
    """
    Verify the constraints of :paramref:`that` recursively.

    :param that: instance whose constraints we want to verify
    :yield: constraint violations
    """
    yield from _TRANSFORMER.transform(that)


